let raw = $input.first().json;
while (raw.body && typeof raw.body === 'object') {
  raw = raw.body;
}

const props = raw.properties || {};

let linkDiscovery = "";
const getPropValue = (p) => {
  if (!p) return "";
  if (typeof p === 'string') return p;
  if (p.url) return p.url;
  if (p.email) return p.email;
  if (p.rich_text && p.rich_text[0]) return p.rich_text[0].plain_text || p.rich_text[0].text?.content || "";
  if (p.title && p.title[0]) return p.title[0].plain_text || p.title[0].text?.content || "";
  return "";
};

const notionEmails = [];
for (const [k, v] of Object.entries(props)) {
  if (v.email) notionEmails.push(v.email);
  if (v.people) {
    v.people.forEach(p => {
      if (p.person && p.person.email && !p.person.email.includes('@xtract.app')) {
        notionEmails.push(p.person.email);
      }
    });
  }
  if (k.toLowerCase().includes('mail') || k.toLowerCase().includes('correo') || k.toLowerCase().includes('email')) {
    const val = getPropValue(v);
    if (val && val.includes('@') && !val.includes('@xtract.app')) notionEmails.push(val);
  }
}

// Buscar link de discovery en props
for (const [k, v] of Object.entries(props)) {
  if (k.toLowerCase().includes('discovery') || k.toLowerCase().includes('transcrip') || k.toLowerCase().includes('drive') || k.toLowerCase().includes('doc')) {
    const val = getPropValue(v);
    if (val && (val.includes('drive.google.com') || val.includes('docs.google.com'))) {
      linkDiscovery = val;
      break;
    }
  }
}

// Buscar link de discovery en campos planos de raw
if (!linkDiscovery) {
  for (const [k, v] of Object.entries(raw)) {
    if (typeof v === 'string' && (v.includes('drive.google.com') || v.includes('docs.google.com'))) {
      linkDiscovery = v;
      break;
    }
  }
}

let fileId = "";
const match = (linkDiscovery || "").match(/\/d\/([a-zA-Z0-9_-]+)/);
if (match) {
  fileId = match[1];
} else {
  const matchId = (linkDiscovery || "").match(/id=([a-zA-Z0-9_-]+)/);
  if (matchId) fileId = matchId[1];
}

let empresa = "";
for (const [k, v] of Object.entries(props)) {
  if (k.toLowerCase().includes('empresa') || k.toLowerCase().includes('name') || k.toLowerCase().includes('title') || k.toLowerCase().includes('cliente')) {
    empresa = getPropValue(v);
    if (empresa) break;
  }
}
if (!empresa) empresa = raw.property_nombre_oportunidad || raw.empresa || raw.name || "Cliente";

let ownerEmail = raw.owner || raw.ownerEmail || "nicolas.gonzalez@xtract.app";
for (const [k, v] of Object.entries(props)) {
  if (k.toLowerCase().includes('owner') || k.toLowerCase().includes('responsable')) {
    if (v.people && v.people[0] && v.people[0].person && v.people[0].person.email) {
      ownerEmail = v.people[0].person.email;
      break;
    }
  }
}

let interlocutor = "";
for (const [k, v] of Object.entries(props)) {
  if (k.toLowerCase().includes('contacto') || k.toLowerCase().includes('persona') || k.toLowerCase().includes('asistente')) {
    interlocutor = getPropValue(v);
    if (interlocutor) break;
  }
}

const rawId = (raw.id || raw.page_id || "").replace(/-/g, "");
const notionUrl = raw.url || (rawId ? ("https://www.notion.so/" + rawId) : "");

return [{ json: {
  fileId,
  linkDiscovery,
  empresa,
  interlocutor,
  ownerEmail,
  notionUrl,
  notionEmails,
  raw
} }];

// =====================================================================
// PREPARAR TRANSCRIPCION -- limpieza, guardas y control de largo.
// =====================================================================
const notion = $('Code - Extraer Datos').first().json || {};
let txt = String($input.first().json.data || '').replace(/\r/g, '').trim();

// ---------------------------------------------------------------------
// GUARDA 1: TRANSCRIPCION VACIA.
// Sin esto el fallo es SILENCIOSO: el modelo no recibe nada, igual
// devuelve un mail creible y generico, y sale al comercial listo para
// enviar. Causa mas comun: /export de Drive solo exporta Docs NATIVOS de
// Google; si el link de Notion apunta a un PDF o a un .docx subido,
// contesta 403 y aca llega vacio.
// ---------------------------------------------------------------------
if (!txt) {
  throw new Error(
    'La transcripcion llego vacia. Revisa que "Link a discovery" de la card ' +
    (notion.notionUrl || '') + ' apunte a un Google Doc NATIVO: /export no exporta PDFs ni archivos subidos.'
  );
}

// ---------------------------------------------------------------------
// LIMPIEZA DEL FORMATO.
// El transcript repite el nombre del hablante en CADA linea y parte las
// frases en fragmentos ("Hola," / "como estas," / "Nicolas?"). Medido en
// una llamada real: 416 lineas, 30% de los caracteres gastados en repetir
// nombres, 53% de las lineas con menos de 25 chars de contenido.
// Agrupando por hablante y usando etiquetas cortas se reduce ~25%.
// ---------------------------------------------------------------------
const norm = (s) => String(s == null ? '' : s).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();
const comercialNorm = norm(String(notion.ownerEmail || '').split('@')[0].replace(/[._]/g, ' '));
const PREF = /^([^:]{1,60}):\s*(.*)$/;

const lineas = txt.split('\n').map((l) => l.trim()).filter(Boolean);
const bloques = [];
let etqActual = null;
let buffer = [];
for (const l of lineas) {
  const m = PREF.exec(l);
  if (m) {
    const hablante = norm(m[1]);
    const contenido = m[2].trim();
    // El comercial se identifica por el owner de la card; todo lo demas es cliente.
    const etq = (comercialNorm && hablante.indexOf(comercialNorm.split(' ')[0]) !== -1) ? 'XTRACT' : 'CLIENTE';
    if (etq === etqActual) { if (contenido) buffer.push(contenido); }
    else {
      if (etqActual && buffer.length) bloques.push(etqActual + ': ' + buffer.join(' '));
      etqActual = etq; buffer = contenido ? [contenido] : [];
    }
  } else if (etqActual) { buffer.push(l); }
}
if (etqActual && buffer.length) bloques.push(etqActual + ': ' + buffer.join(' '));

// Pie automatico del transcriptor: no es dialogo, es ruido.
let limpio = bloques
  .filter((b) => !/transcripci[oó]n editable se gener[oó] autom[aá]ticamente|la reuni[oó]n finaliz[oó] despu[eé]s de/i.test(b))
  .join('\n')
  .trim();
if (!limpio) limpio = txt;   // si el formato no era el esperado, se usa el crudo

// ---------------------------------------------------------------------
// GUARDA 2: ¿LA LLAMADA ES DE ESTA EMPRESA?
// La card de Notion trae el nombre autoritativo. Si ese nombre no aparece
// en la transcripcion, la card tiene enlazado el Doc de OTRA empresa.
// Caso real: la card "Comercializadora Andina" apuntaba al discovery de
// CRETA DISEGNO, y salio un borrador con las dos empresas adentro, listo
// para enviar.
// Se compara por tokens: alcanza con que UNO aparezca, porque los
// transcriptores deforman los nombres ("Cretadisegn" por "CRETA DISEGNO").
// ---------------------------------------------------------------------
const GENERICAS = ['comercializadora','distribuidora','grupo','empresa','compania','company','sa','srl','sas','spa','ltda','ltd','inc','corp','cia','holding','servicios','soluciones','group'];
// Proveedores gratuitos y TLDs: no dicen nada de la empresa.
const FREEMAIL = ['gmail','hotmail','outlook','yahoo','live','icloud','aol','protonmail','msn','terra','fibertel','speedy'];
const TLD = ['com','net','org','ar','co','mx','cl','pe','uy','br','es','io','app','info','biz'];

// ---------------------------------------------------------------------
// DE DONDE SALEN LOS TOKENS QUE IDENTIFICAN A LA EMPRESA.
//
// Medido sobre la base real: de 12 cards con discovery cargado, OCHO
// tienen un EMAIL como nombre de oportunidad en vez del nombre de la
// empresa ("crossettiroberto@gmail.com", "valcara@christianhansen.com.ar").
// Validar contra la parte local del correo rechazaria cards legitimas:
// "crossettiroberto" no va a aparecer nunca en una transcripcion.
//
// Por eso: si el nombre es un email, lo unico aprovechable es el DOMINIO,
// y solo cuando no es un proveedor gratuito. Si no queda ningun token
// util, NO se valida y se deja pasar -- la guarda existe para atajar un
// doc cruzado, no para bloquear por como esta cargada la card.
// ---------------------------------------------------------------------
const nombreEmpresa = String(notion.empresa || '').trim();
let tokens;
if (nombreEmpresa.indexOf('@') !== -1) {
  const dominio = nombreEmpresa.split('@')[1] || '';
  tokens = norm(dominio).split(' ').filter((t) => t.length >= 4 && TLD.indexOf(t) === -1 && FREEMAIL.indexOf(t) === -1 && GENERICAS.indexOf(t) === -1);
} else {
  tokens = norm(nombreEmpresa).split(' ').filter((t) => t.length >= 4 && GENERICAS.indexOf(t) === -1);
}
// OJO: se valida contra el texto ORIGINAL, no contra el limpio. La limpieza
// reemplaza los nombres de hablante por CLIENTE:/XTRACT:, y en estos
// transcripts la empresa suele venir JUSTO ahi ("Noelia Sierra - CRETA
// DISEGNO:"). Validando contra el limpio se rechazaban llamadas correctas.
const crudoNorm = norm(txt);
if (tokens.length && !tokens.some((t) => crudoNorm.indexOf(t) !== -1)) {
  throw new Error(
    'La transcripcion no corresponde a "' + notion.empresa + '": ninguno de [' + tokens.join(', ') +
    '] aparece en la llamada. Revisa el "Link a discovery" de ' + (notion.notionUrl || 'la card') +
    ' -- probablemente tenga adjunto el Doc de otra empresa.'
  );
}

// ---------------------------------------------------------------------
// LARGO. El tope anterior era 22.000 y cortaba por el FINAL, que es donde
// se hablan proximos pasos y compromisos: en una llamada real se perdian
// 9.180 caracteres. El modelo tiene 64k de contexto, asi que el tope sube.
// Si aun asi hay que cortar, se corta el MEDIO y se conservan las dos
// puntas: el arranque tiene el contexto y el cierre los acuerdos.
// ---------------------------------------------------------------------
// 120.000 chars ~ 35k tokens: una discovery de dos horas entra completa y
// sigue sobrando contexto. En la practica esto ya no trunca nunca; el corte
// queda solo como red por si llega un archivo raro.
const MAX = 120000;
if (limpio.length > MAX) {
  const mitad = Math.floor(MAX / 2);
  limpio = limpio.slice(0, mitad) + '\n\n[...tramo intermedio omitido por longitud...]\n\n' + limpio.slice(-mitad);
}

return [{ json: {
  transcripcion: limpio,
  chars_originales: txt.length,
  chars_finales: limpio.length,
  empresa_validada: notion.empresa || ''
} }];

