{
  "type": "object",
  "properties": {
    "interlocutores": {
      "type": "string",
      "description": "Nombres de las personas del cliente (ej: Paula y equipo, Pedro y Emily, Freddy y equipo, Noe)"
    },
    "emails_destinatarios": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Emails de los interlocutores del cliente mencionados en la llamada. Si no se mencionaron explícitamente, devolver array vacío [] — no inventar correos."
    },
    "saludo_intro": {
      "type": "string",
      "description": "Frase de saludo inicial y agradecimiento por la reunión adaptada al tono de la charla."
    },
    "desafios_puntos": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "De 3 a 7 bullets con los dolores relevados, en las PALABRAS DEL CLIENTE. Maximo 20 palabras por bullet. NO dejes afuera un dolor real por acortar: es preferible un mail algo mas largo que uno que se olvide algo que el cliente dijo. Solo hechos dichos en la llamada; sin interpretaciones ni soluciones."
    },
    "solucion_encaje": {
      "type": "string",
      "description": "UNA sola oracion, maximo 35 palabras, que conecte el diagnostico con lo que hace Xtract. Es un puente, NO un pitch: nada de plazos, precios, modulos, conectores nativos ni propuesta comercial. Si no se puede decir en una oracion sin inventar, devolver string vacio."
    },
    "menciono_validacion_tecnica": {
      "type": "boolean",
      "description": "true si en la llamada se habló de integraciones por API, validar viabilidad con el equipo técnico o conectar con proveedores de ERP (Fénix, SAP, NetSuite, etc.)."
    },
    "cierre_despedida": {
      "type": "string",
      "description": "Una linea de cierre cordial, maximo 12 palabras. Sin ofrecer reuniones ni proximos pasos."
    },
    "erp_detectado": {
      "type": "string",
      "description": "Nombre EXACTO del ERP o sistema de gestion que el cliente dijo que usa hoy (ej: SAP, SAP B1, SAP ECC, NetSuite, Oracle, Siigo, Tango, Odoo, Finnegans, Intec). Devolver string vacio \"\" si no se menciono ninguno o si no quedo claro. PROHIBIDO inventarlo o deducirlo: se usa para decidir si mostrarle un caso de exito de su mismo sistema, y equivocarse ahi es peor que no mostrar nada."
    }
  },
  "required": [
    "interlocutores",
    "saludo_intro",
    "desafios_puntos",
    "solucion_encaje"
  ],
  "description": "Mail POST-DISCOVERY unicamente. Objetivo: demostrar entendimiento y construir confianza. Tono cercano, empatico y reflexivo, de consultor que escucha. SIN VENTA NI URGENCIA. Apunta a 140-180 palabras, pero PRIMERO cubri todo lo que se hablo: si hacen falta 200 para no dejar afuera un dolor real, usalas. Hay UN SOLO CTA y lo agrega el sistema. NO propongas propuestas comerciales, referencias ni plazos de implementacion."
}

parameters.jsCode:
// =====================================================================
// MODO PRUEBA -- UNICO LUGAR PARA CAMBIARLO
//
// Con un valor cargado, TODOS los borradores van a este DM y NUNCA al
// comercial real. Para pasar a produccion, dejarlo en '' (string vacio).
//
// Existe porque el 28/08 el borrador de Creta Disegno le llego a Nicolas
// creyendo que estabamos probando: este workflow no tenia interruptor y
// la tabla KNOWN_OWNERS resuelve al comercial siempre. El DM de respaldo
// (SLACK_FALLBACK_DM) NO alcanza: solo actua cuando NO se pudo resolver
// al owner, que casi nunca pasa.
// =====================================================================
const FORZAR_DESTINATARIO = 'U0BJLTDCAMR';   // member id de Santiago en su workspace (T0BJPS3C3NH)

const notion = $('Code - Extraer Datos').first().json || {};
const iaRaw = $('IA - Redactar borrador de correo').first().json || {};
const ia = iaRaw.output || iaRaw;

// 1. Resolver Destinatarios (Emails del cliente)
const emailsNotion = Array.isArray(notion.emails) ? notion.emails : (notion.emails ? [notion.emails] : []);
const emailsIa = Array.isArray(ia.emails_destinatarios) ? ia.emails_destinatarios : (ia.emails_destinatarios ? [ia.emails_destinatarios] : []);
const todosEmails = [...new Set([...emailsNotion, ...emailsIa].map(e => String(e || '').trim().toLowerCase()))].filter(e => e && e.includes('@'));
const paraTexto = todosEmails.length ? todosEmails.join(', ') : '*(Completar emails de los interlocutores)*';

// 2. Nombres y Comercial
const interlocutores = (ia.interlocutores || notion.persona || 'equipo').trim();
const rawOwner = (Array.isArray(notion.owner) ? notion.owner[0] : notion.owner) || notion.ownerEmail || '';
const ownerLocal = rawOwner.split('@')[0].replace(/[._-]+/g, ' ');
const nombreComercial = ownerLocal ? ownerLocal.split(' ').map(w => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase()).join(' ') : 'Nicolás';

// 3. Construir Bloques del Correo
const saludo = ia.saludo_intro || ('Hola ' + interlocutores + ', buenas tardes.\nGracias nuevamente por el tiempo de hoy.');

// Bullets de desafíos
const puntos = Array.isArray(ia.desafios_puntos) ? ia.desafios_puntos : (ia.desafios_puntos ? [ia.desafios_puntos] : []);
// TOPE DE 7 BULLETS.
// Estaba en 5 para respetar el maximo de 180 palabras de la espec, pero eso
// hacia perder dolores reales en llamadas largas. Decision explicita del
// usuario: PRIMERO cubrir toda la informacion, despues el largo. El tope
// queda como freno de mano por si el modelo se dispara.
const puntosCortados = puntos.slice(0, 7);
const bloqueDesafios = puntosCortados.length
  ? puntosCortados.map((p) => '• ' + String(p).replace(/^[•\-\*]\s*/, '').trim()).join('\n')
  : (ia.desafio || '');

// Párrafo de solución
const bloqueSolucion = ia.solucion_encaje || ia.solucion || '';

// La documentacion de API NO va en el post-discovery: es un segundo
// pedido ("que el equipo tecnico valide") y compite con el CTA de
// validacion. Se conserva la senal para los mails siguientes.
const pidioValidacionTecnica = ia.menciono_validacion_tecnica === true;

// =====================================================================
// CTA UNICO -- VALIDACION DEL DIAGNOSTICO.
//
// Antes salia 'bloqueProximos' con lo que devolvia la IA, que proponia
// demo + propuesta comercial + referencias. Medido contra la espec del
// mail post-discovery eran CINCO CTAs y 470 palabras, cuando el maximo
// es UNO y 180.
//
// El post-discovery no vende: valida. El unico pedido es que confirmen
// si entendimos bien como trabajan. La demo y la propuesta van en los
// mails siguientes de la secuencia.
// =====================================================================
// =====================================================================
// CTA UNICO -- COORDINAR LA LLAMADA, CON LA VALIDACION ADENTRO.
//
// La espec del post-discovery pedia como CTA solo validar el diagnostico,
// pero en la practica este mail YA coordina la siguiente llamada. Se
// fusionan en UNA sola frase a proposito: pedir las dos cosas por separado
// serian dos CTAs, y la regla es uno.
//
// El pedido principal es la llamada; la validacion viaja de arrastre, sin
// obligar al cliente a contestar dos cosas.
// =====================================================================
const bloqueCta = '\nSi te parece, coordinamos una llamada para mostrarte cómo se vería esto en la práctica — y de paso me confirmás si interpreté bien el diagnóstico o hay algo que se me esté escapando.';

// =====================================================================
// CASO DE EXITO -- SOLO SI EL SISTEMA DEL CLIENTE MATCHEA DE VERDAD.
//
// Antes esto era un bloque FIJO con dos videos que salian siempre, y
// encima los dos apuntaban al mismo ID (k2uYl5kSGBQ, que es el de MODO):
// el link de Pomelo estaba mal desde el principio.
//
// Mandarle un caso de SAP a alguien que usa Siigo es peor que no mandar
// nada: muestra que no escuchamos. Por eso, sin match certero NO VA NADA.
//
// Solo entran casos con CLIENTE NOMBRADO. Quedaron afuera a proposito:
//   - MODO: su match seria "es fintech", y eso no se detecta con certeza
//     desde una transcripcion.
//   - El video de Xero: no tiene cliente nombrado, es demo. No es prueba
//     social.
// =====================================================================
const CASOS_POR_SISTEMA = [
  { re: /\bsap\b/i,      titulo: 'Pomelo automatizo la contabilizacion de facturas sobre SAP', url: 'https://www.youtube.com/watch?v=ikDLA5HjQbs' },
  { re: /netsuite/i,      titulo: 'InvGate automatizo la contabilizacion de facturas en NetSuite', url: 'https://www.youtube.com/watch?v=4xFCkoxat1o' }
];

const erpDetectado = String(ia.erp_detectado || '').trim();
let bloqueCasosExito = '';
if (erpDetectado) {
  const caso = CASOS_POR_SISTEMA.find((x) => x.re.test(erpDetectado));
  if (caso) {
    bloqueCasosExito = '\nPor si les sirve, un equipo que venia con el mismo sistema: <' + caso.url + '|' + caso.titulo + '>.';
  }
}

// Cierre y firma
// =====================================================================
// EL CIERRE NO PUEDE OFRECER UNA REUNION.
//
// El schema se lo prohibe, pero se le colo igual: en la corrida de Creta
// devolvio "Quedo atento a tu confirmacion para coordinar la demo". Eso
// mete un SEGUNDO pedido justo debajo del CTA de validacion, que es
// exactamente lo que la espec del post-discovery prohibe.
//
// Se sanea aca en vez de volver a pedirselo al prompt: si la frase
// menciona demo, reunion, llamada o propuesta, se descarta entera y se
// usa un cierre neutro.
// =====================================================================
const OFRECE_REUNION = /\b(demo|demostraci[oó]n|reuni[oó]n|videollamada|llamada|call|propuesta|invitaci[oó]n|agendar|coordinar|disponibilidad)\b/i;
const cierreIa = String(ia.cierre_despedida || '').trim();
const cierreLimpio = (cierreIa && !OFRECE_REUNION.test(cierreIa)) ? cierreIa : 'Quedo atento a sus comentarios.';
const cierre = cierreLimpio + '\n' + nombreComercial;

// 4. Ensamble del Borrador Completo
const cuerpoEmail = [
  saludo,
  '',
  'Por lo que conversamos, hoy el principal desafío está en:',
  bloqueDesafios,
  '',
  bloqueSolucion,
  bloqueCasosExito,
  bloqueCta,
  '',
  cierre
].filter(x => x !== undefined && x !== null && x !== '').join('\n').replace(/\n{3,}/g, '\n\n');

// Control de largo: la espec pide 140-165 palabras, maximo 180. El conteo
// viaja hasta Slack para que se vea si un borrador se paso, en vez de
// enterarnos cuando el comercial ya lo mando.
const palabrasMail = cuerpoEmail.replace(/<[^|>]+\|([^>]+)>/g, '$1').split(/\s+/).filter(Boolean).length;
// El conteo viaja SIEMPRE para ver la tendencia. La alarma recien salta en
// 220: por debajo de eso se prefiere un mail algo mas largo antes que uno
// que deje afuera algo que el cliente dijo.
const avisoLargo = palabrasMail > 220 ? ('\n:warning: *' + palabrasMail + ' palabras* — quedo largo, conviene revisarlo.') : ('\n_' + palabrasMail + ' palabras_');

// 5. Matching en Cascada para encontrar el ID de Slack del Comercial
const norm = s => String(s == null ? '' : s).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().trim();
const emailNorm = norm(rawOwner);
const local = norm(rawOwner.split('@')[0]);
const comoNombre = local.replace(/[._-]+/g, ' ');

// Tabla estática de resguardo por si users.list tiene rate limit 429
const KNOWN_OWNERS = {
  'nicolas.gonzalez@xtract.app': 'U02MCAHHM1T',
  'wenceslao.hoepner@xtract.app': 'U0BBASA0F60',
  'damian.deggeller@xtract.app': 'U09PYEWUHGF',
  'greta.bruno@xtract.app': 'U096BLX5864',
  'ian.brandan@xtract.app': 'U09FZ5MLF0E'
};

// El nodo nativo de Slack devuelve UN ITEM POR USUARIO, no un objeto
// {members:[...]} como la llamada HTTP cruda. Se leen con .all().
// Se deja el fallback a la forma vieja por si el nodo vuelve a cambiar.
let usuarios = [];
try {
  usuarios = $('Slack - Traer usuarios').all()
    .map((i) => i.json)
    .filter((u) => u && u.id && !u.deleted && !u.is_bot);
  if (!usuarios.length) {
    const raw = $('Slack - Traer usuarios').first().json || {};
    usuarios = (raw.members || raw.users || []).filter((u) => u && u.id && !u.deleted && !u.is_bot);
  }
} catch (e) {}

const perfil = u => u.profile || {};
let owner = usuarios.find(u => norm(perfil(u).email) === emailNorm) || null;
if (!owner) owner = usuarios.find(u => norm(u.name) === local) || null;
if (!owner) owner = usuarios.find(u => norm(perfil(u).display_name) === local) || null;
if (!owner) owner = usuarios.find(u => norm(u.real_name) === comoNombre) || null;
if (!owner) owner = usuarios.find(u => norm(perfil(u).real_name) === comoNombre) || null;

// D0BRPUE84UA era el DM de OTRO bot: nunca funciono. El fallback correcto
// es el member id, para que Slack abra la conversacion.
const SLACK_FALLBACK_DM = 'U0BJLTDCAMR';
const ownerSlackIdReal = owner ? owner.id : (KNOWN_OWNERS[emailNorm] || SLACK_FALLBACK_DM);
const ownerSlackId = FORZAR_DESTINATARIO || ownerSlackIdReal;
const enModoPrueba = !!FORZAR_DESTINATARIO;
const esFallback = !owner && !KNOWN_OWNERS[emailNorm];

// Link a Notion
const rawId = (notion.id || notion.page_id || '').replace(/-/g, '');
const notionUrl = notion.url || (rawId ? ('https://www.notion.so/' + rawId) : '');
const empresa = notion.property_nombre_oportunidad || notion.empresa || 'Cliente';

// 6. Mensaje Formateado para Slack
const textoSlack = [
  // El cartel va PRIMERO y sin ambiguedad: un borrador de prueba es
  // indistinguible de uno real, y el riesgo es que alguien lo copie y lo
  // mande al cliente.
  (enModoPrueba ? ':test_tube: *MODO PRUEBA* — en produccion esto le hubiera llegado a `' + ownerSlackIdReal + '`' : ''),
  ':incoming_envelope: *Borrador de Email Post-Discovery* — ' + empresa,
  (notionUrl ? '• <' + notionUrl + '|Abrir card en Notion>' : ''),
  (esFallback ? '_Nota: Enviado a fallback de pruebas._' : ''),
  '',
  '━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━',
  '*Para:* ' + paraTexto,
  '*Subject:* Resumen de nuestra reunión + Próximos pasos — Xtract',
  '━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━',
  '',
  cuerpoEmail,
  '',
  '━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━',
  avisoLargo,
  '_Listo para copiar y enviar en Gmail / Outlook._'
].filter(Boolean).join('\n');

return [{ json: {
  texto_slack: textoSlack,
  cuerpo_email: cuerpoEmail,
  palabras_mail: palabrasMail,
  erp_detectado: erpDetectado,
  para: paraTexto,
  subject: 'Resumen de nuestra reunión + Próximos pasos — Xtract',
  owner_slack_id: ownerSlackId,
  comercial: nombreComercial,
  empresa: empresa,
  notion_url: notionUrl
} }];
